import game.agent.eval.*;import game.agent.llm.*;import game.agent.runtime.*;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;
/** Private synthetic experiment. Official provider, bounded separate ledger; no public cookie or quota manipulation. */
public class BudgetedRealMatrix {
 static Map<String,Object> compact(Map<String,Object> row){Map<String,Object> out=new LinkedHashMap<>(row);for(String key:List.of("initialWorld","finalWorld","trace","providerCalls","events","battleTrace"))out.remove(key);return out;}
 public static void main(String[] args)throws Exception{
  int ceiling=args.length>1?Integer.parseInt(args[1]):250000;if(ceiling<1||ceiling>300000)throw new IllegalArgumentException("PRIVATE_TOKEN_CEILING_INVALID");Path root=Path.of(args[0]);Files.createDirectories(root);Map<String,String> env=new HashMap<>(System.getenv());
  env.put("PUBLIC_ORIGIN","https://synthetic-eval.invalid");env.put("LLM_PROVIDER","deepseek");env.put("EVAL_PUBLIC_DEEPSEEK_ENABLED","true");env.put("DEEPSEEK_MODEL","deepseek-flash");env.put("DEEPSEEK_TIMEOUT_MS","60000");env.put("AI_BUDGET_FILE",root.resolve("ai-budget.json").toString());env.put("AI_DAILY_TOKENS",String.valueOf(ceiling));env.put("AI_MONTHLY_TOKENS",String.valueOf(ceiling));env.put("AI_REQUESTS_PER_MINUTE","12");env.put("AI_CONCURRENCY","1");
  EvaluationProviders providers=EvaluationProviders.environment(env);if(!providers.models().contains("deepseek-flash"))throw new IllegalStateException("PROVIDER_NOT_CONFIGURED");
  ExecutorService pool=Executors.newSingleThreadExecutor();List<Map<String,Object>> reports=new ArrayList<>();long[] next={0};
  try{for(long seed:new long[]{11,23,37})for(String scenario:Arrays.asList("shared","competition","fault","battle","forest","information"))for(String model:new String[]{"baseline","deepseek-flash"}){
   Map<String,Object> spec=Json.object("id",UUID.randomUUID().toString(),"scenario",scenario,"seed",seed,"repetition",1,"model",model,"starter","TREECKO","decisions",100,"wallMillis",180000,"price",Collections.emptyMap());EvaluationRun run=new EvaluationRun(spec);String name=scenario+"-"+seed+"-"+model;
   Path saved=root.resolve(name+".json");if(Files.isRegularFile(saved)){Map<String,Object> existing=Json.asObject(Json.read(Files.readString(saved)));reports.add(compact(existing));continue;}AgentLoop.DecisionProvider provider=providers.create(model);AgentLoop.DecisionProvider paced=new AgentLoop.DecisionProvider(){public game.agent.tools.ToolRequest decide(AgentLoop.Context c){try{if(!model.equals("baseline")){long delay=next[0]-System.currentTimeMillis();if(delay>0)Thread.sleep(delay);next[0]=System.currentTimeMillis()+6100;}return provider.decide(c);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("CANCELLED");}}public Map<String,Number> getUsage(){return provider.getUsage();}};
   run.usageJournal(row->{try{Files.writeString(root.resolve(name+"-usage.json"),Json.write(row));}catch(Exception e){throw new IllegalStateException("USAGE_LEDGER_FAILED");}});
   run.resume(paced,pool,providers.timeout());while(!run.terminal()){run.tick(System.currentTimeMillis());Thread.sleep(20);}Map<String,Object> report=run.report(true);reports.add(compact(report));Files.writeString(root.resolve(name+".json"),Json.write(report));Files.writeString(root.resolve("matrix.json"),Json.write(Json.object("codeRevision",env.get("BENCH_COMMIT"),"model","deepseek-flash","syntheticOnly",true,"privateTokenCeiling",ceiling,"paidPlanned",18,"cases",reports,"comparison",EvaluationStatistics.compare(reports))));System.out.println(name+" "+run.status());
  }}finally{pool.shutdownNow();}
 }
}
